(function () {
  'use strict';
  // Salary increase: the raise entered as a percentage, a dollar amount or a new salary.
  //   new = current x (1 + pct)  |  current + amount  |  new;  pct = (new - current) / current
  //   Pay per period = annual / 12, 24, 26, 52; hourly = annual / (hours per week x 52)
  //   Projection: year 1 = new salary, year k = new x (1 + future raise)^(k-1);
  //   in today's dollars = salary / (1 + inflation)^(k-1); cumulative = running total.
  // Verified (Node, scratch tests, hand-checked): $60,000 + 4% -> $62,400.00 (+$2,400.00), monthly
  //   $5,200.00 vs $5,000.00, biweekly $2,400.00 vs $2,307.69, hourly at 40 h $30.00 vs $28.85.
  //   $60,000 -> $66,000 new salary = 10%; +$3,000 = 5%. Projection $62,400 at 3% for 10 years:
  //   year 10 = $62,400 x 1.03^9 = $81,417.85, total = $62,400 x (1.03^10 - 1) / 0.03
  //   = $715,346.07; at 2.5% inflation year 10 in today's dollars = $81,417.85 / 1.025^9
  //   = $65,193.58 (independent Python check). 0% raises give flat rows; current salary 0 is rejected (no Infinity).
  //   Whole script run under Node with a stub DOM: no NaN/Infinity reaches the page.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var PERIODS = [['Annual', 1], ['Monthly', 12], ['Twice a month', 24], ['Every two weeks', 26], ['Weekly', 52]];

  function raise(current, type, value) {
    var next = type === 'percent' ? current * (1 + value / 100) : type === 'amount' ? current + value : value;
    return { current: current, next: next, change: next - current, pct: (next - current) / current };
  }

  function project(start, growth, inflation, years) {
    var rows = [], total = 0;
    for (var k = 1; k <= years; k++) {
      var salary = start * Math.pow(1 + growth, k - 1);
      total += salary;
      rows.push({ year: k, salary: salary, real: salary / Math.pow(1 + inflation, k - 1), total: total });
    }
    return rows;
  }

  function readNum(id, blankValue) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    if (el.value === '' && blankValue !== undefined) return blankValue;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function show(id, on) { var el = document.getElementById(id); if (el) el.hidden = !on; }
  function signedMoney(v) { return (v < -0.005 ? '−' : '+') + money.format(Math.abs(v)); }
  function signedPct(v) { return (v < -0.00005 ? '−' : '+') + Math.abs(v * 100).toFixed(2) + '%'; }

  function fillTable(id, rows) {
    var body = document.getElementById(id);
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['siNew', 'siChange', 'siPct', 'siMonthly', 'siFinal', 'siTotal'].forEach(function (id) { set(id, '–'); });
    fillTable('siPeriods', []);
    fillTable('siSchedule', []);
  }

  function update() {
    var typeEl = document.getElementById('siType');
    var type = typeEl && ['percent', 'amount', 'new'].indexOf(typeEl.value) !== -1 ? typeEl.value : 'percent';
    show('siPctField', type === 'percent');
    show('siAmtField', type === 'amount');
    show('siNewField', type === 'new');

    var current = readNum('siSalary');
    var value = readNum(type === 'percent' ? 'siRaisePct' : type === 'amount' ? 'siRaiseAmt' : 'siNewSalary');
    var growth = readNum('siFuture', 0), years = readNum('siYears'), inflation = readNum('siInflation', 0), hours = readNum('siHours', 40);
    var msg = '';
    if (!isFinite(current) || current <= 0 || current > 1e10) msg = 'Enter a current salary above 0.';
    else if (!isFinite(value) || Math.abs(value) > 1e10) msg = 'Enter the raise as a number.';
    else if (type === 'percent' && (value < -100 || value > 1000)) msg = 'Enter a raise from −100% to 1,000%.';
    else if (type === 'amount' && current + value < 0) msg = 'A pay cut cannot be larger than the current salary.';
    else if (type === 'new' && value < 0) msg = 'Enter a new salary of 0 or more.';
    else if (!isFinite(growth) || growth < -50 || growth > 100) msg = 'Enter future yearly raises from −50% to 100%.';
    else if (!isFinite(years) || years < 1 || years > 50 || Math.round(years) !== years) msg = 'Enter 1 to 50 whole years to project.';
    else if (!isFinite(inflation) || inflation < 0 || inflation > 50) msg = 'Enter an inflation rate from 0 to 50%.';
    else if (!isFinite(hours) || hours <= 0 || hours > 168) msg = 'Enter hours per week from 1 to 168.';
    var error = document.getElementById('siError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var r = raise(current, type, value);
    set('siNew', money.format(r.next));
    set('siChange', signedMoney(r.change));
    set('siPct', signedPct(r.pct));
    set('siMonthly', signedMoney(r.change / 12));

    var rows = PERIODS.map(function (p) {
      return [p[0], money.format(r.current / p[1]), money.format(r.next / p[1]), signedMoney(r.change / p[1])];
    });
    var perYearHours = hours * 52;
    rows.push(['Hourly (' + hours + ' h/week)', money.format(r.current / perYearHours), money.format(r.next / perYearHours), signedMoney(r.change / perYearHours)]);
    fillTable('siPeriods', rows);

    var proj = project(r.next, growth / 100, inflation / 100, years);
    var last = proj[proj.length - 1];
    set('siFinal', money.format(last.salary));
    set('siTotal', money.format(last.total));
    set('siFinalLabel', 'Salary in year ' + years);
    set('siTotalLabel', 'Total earned over ' + years + (years === 1 ? ' year' : ' years'));
    fillTable('siSchedule', proj.map(function (p) {
      return [String(p.year), money.format(p.salary), money.format(p.real), money.format(p.total)];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('siForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
